glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 v_uv;
out vec4 v_color;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  pos = cc_matViewProj * pos;
  v_uv = a_texCoord;
  v_color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec2 v_uv;
in vec4 v_color;
layout(std140) uniform Props {
  vec4 lightColor;
  vec4 uvOrigin;
  vec4 uvAxisY;
  float apexX;
  float coneWidth;
  float edgeSoftness;
  float attenuation;
};
vec4 frag () {
  vec2 d = v_uv - uvOrigin.xy;
  vec2 ax = uvOrigin.zw;
  vec2 ay = uvAxisY.xy;
  vec2 uv;
  uv.x = dot(d, ax) / max(dot(ax, ax), 1e-8);
  uv.y = dot(d, ay) / max(dot(ay, ay), 1e-8);
  float distFromTop = uv.y;
  float halfWidth = coneWidth * 0.5 * distFromTop;
  float distFromCenter = abs(uv.x - apexX);
  float shape = 1.0 - smoothstep(halfWidth - edgeSoftness, halfWidth, distFromCenter);
  float fade = 1.0 - pow(distFromTop, attenuation);
  float alpha = shape * fade * v_color.a;
  return vec4(lightColor.rgb * alpha * lightColor.a, alpha * lightColor.a);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

glsl1.vert:
precision highp float;
uniform highp mat4 cc_matViewProj;
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec2 v_uv;
varying vec4 v_color;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  pos = cc_matViewProj * pos;
  v_uv = a_texCoord;
  v_color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl1.frag:
precision highp float;
varying vec2 v_uv;
varying vec4 v_color;
  uniform vec4 lightColor;
  uniform vec4 uvOrigin;
  uniform vec4 uvAxisY;
  uniform float apexX;
  uniform float coneWidth;
  uniform float edgeSoftness;
  uniform float attenuation;
vec4 frag () {
  vec2 d = v_uv - uvOrigin.xy;
  vec2 ax = uvOrigin.zw;
  vec2 ay = uvAxisY.xy;
  vec2 uv;
  uv.x = dot(d, ax) / max(dot(ax, ax), 1e-8);
  uv.y = dot(d, ay) / max(dot(ay, ay), 1e-8);
  float distFromTop = uv.y;
  float halfWidth = coneWidth * 0.5 * distFromTop;
  float distFromCenter = abs(uv.x - apexX);
  float shape = 1.0 - smoothstep(halfWidth - edgeSoftness, halfWidth, distFromCenter);
  float fade = 1.0 - pow(distFromTop, attenuation);
  float alpha = shape * fade * v_color.a;
  return vec4(lightColor.rgb * alpha * lightColor.a, alpha * lightColor.a);
}
void main() { gl_FragColor = frag(); }
